from datetime import datetime, timezone
from html.parser import HTMLParser
import json
import sqlite3
from urllib.parse import quote, urlsplit
from xml.etree import ElementTree

import config
import importers
import uniclubs_database


STREAM_CALL = 'self.__next_f.push('


def _detail_path(href):
    """Return an HSG event path for a local public detail link, or None for other links."""
    try:
        url = urlsplit(href)
    except ValueError:
        return None
    if url.netloc and url.netloc != urlsplit(config.UNICLUBS_BASE_URL).netloc:
        return None
    parts = url.path.split('/')
    if (len(parts) == 6 and parts[1:3] == [config.UNICLUBS_UNIVERSITY, 'clubs']
            and parts[3] and parts[4] == 'events' and parts[5]):
        return url.path
    return None


class UniClubsPage(HTMLParser):
    """Read public detail links and JSON stream fragments without executing JavaScript."""

    def __init__(self):
        """Prepare bounded-page parsing with empty fragment and link collections."""
        super().__init__(convert_charrefs=True)
        self.fragments = []
        self.detail_paths = set()
        self.in_script = False
        self.script_parts = []

    def handle_starttag(self, tag, attrs):
        """Collect event links and start collecting a script's text fragments."""
        attributes = dict(attrs)
        if tag == 'script':
            self.in_script = True
            self.script_parts = []
        if tag == 'a':
            path = _detail_path(attributes.get('href') or '')
            if path:
                self.detail_paths.add(path)

    def handle_data(self, data):
        """Keep script data pieces in order, including fragmented parser callbacks."""
        if self.in_script:
            self.script_parts.append(data)

    def handle_endtag(self, tag):
        """Decode complete script text only after its closing tag has arrived."""
        if tag == 'script' and self.in_script:
            self._read_script(''.join(self.script_parts))
            self.in_script = False
            self.script_parts = []

    def _read_script(self, script):
        """Read JSON arguments of the observed Next.js calls; never evaluate their code."""
        position = script.find(STREAM_CALL)
        while position != -1:
            start = position + len(STREAM_CALL)
            try:
                argument, consumed = json.JSONDecoder().raw_decode(script[start:])
            except (ValueError, RecursionError) as error:
                raise ValueError('The public event data stream is incomplete.') from error
            end = start + consumed
            if not script[end:].lstrip().startswith(')'):
                raise ValueError('The public event data stream has an unexpected format.')
            if isinstance(argument, list) and argument and argument[0] == 1:
                if len(argument) != 2 or not isinstance(argument[1], str):
                    raise ValueError('The event stream fragment is not text.')
                self.fragments.append(argument[1])
            position = script.find(STREAM_CALL, end + 1)


def _collect_event_lists(value, found):
    """Walk decoded component data to find the single unauthenticated event-list property."""
    # Course: U03 s3 / L04 – lists and dictionaries; recursion visits their nested children.
    if isinstance(value, dict):
        if 'events' in value and 'isLoggedIn' in value:
            if value['isLoggedIn'] is not False:
                raise ValueError('Only unauthenticated public event data may be imported.')
            found.append(value['events'])
        for child in value.values():
            _collect_event_lists(child, found)
    elif isinstance(value, list):
        for child in value:
            _collect_event_lists(child, found)


def _extract_events(page):
    """Decode component rows after joining all streamed fragments in document order."""
    found = []
    for line in ''.join(page.fragments).splitlines():
        content = line.partition(':')[2].strip()
        if '"events"' not in content or not content.startswith(('[', '{')):
            continue
        try:
            component = json.loads(content)
            _collect_event_lists(component, found)
        except (ValueError, RecursionError) as error:
            raise ValueError('The public event component could not be decoded.') from error
    if len(found) != 1 or not isinstance(found[0], list):
        raise ValueError('Exactly one public event list is required.')
    if not 0 < len(found[0]) <= config.MAX_RECORDS_PER_SOURCE:
        raise ValueError('The source event list is empty or exceeds the allowed size.')
    return found[0]


def _public_text(value, field, required=True):
    """Read literal public text, rejecting missing values and unresolved React references."""
    if value is None and not required:
        return ''
    if not isinstance(value, str) or (required and not value.strip()):
        raise ValueError(f'The public event has invalid {field}.')
    if value.startswith('$$'):
        value = value[1:]  # React escapes an ordinary leading dollar sign this way.
    elif value.startswith('$'):
        raise ValueError(f'The public event has an unresolved {field} reference.')
    return value.strip()


def _slug(value):
    """Validate and encode a public URL path segment without accepting another route."""
    text = _public_text(value, 'slug')
    if text in ('.', '..') or any(character in text for character in ('/', '?', '#')):
        raise ValueError('The source contains an invalid event or club slug.')
    return quote(text, safe='')


def _source_time(value, field, required=True):
    """Remove only the source's date marker, retaining UTC and any subsecond precision."""
    if value is None and not required:
        return None
    if isinstance(value, str) and value.startswith('$D'):
        value = value[2:]
    return uniclubs_database.normalize_utc_time(value, field)


def _club_record(club):
    """Keep only the club's public identity, name and profile link."""
    path = f'/{config.UNICLUBS_UNIVERSITY}/clubs/{_slug(club.get("slug"))}'
    return {'external_id': _public_text(club.get('id'), 'club ID'),
            'name': _public_text(club.get('name'), 'club name'),
            'source_url': config.UNICLUBS_BASE_URL + path}


def _event_record(event, club, availability):
    """Keep calendar metadata, publication status and registration status as distinct values."""
    membership = event.get('requiresMembership')
    if membership is not None and type(membership) is not bool:
        raise ValueError('The membership requirement is not a boolean.')
    start = _source_time(event.get('startDate'), 'startDate')
    end = _source_time(event.get('endDate'), 'endDate', required=False)
    if end is not None and end <= start:
        raise ValueError('The source end must be later than the start.')
    return {
        'external_id': _public_text(event.get('id'), 'event ID'),
        'club_external_id': club['external_id'],
        'title': _public_text(event.get('title'), 'title'),
        'start_utc': start, 'end_utc': end,
        'location': _public_text(event.get('location'), 'location', required=False),
        'event_type': _public_text(event.get('eventType'), 'event type', required=False),
        'source_url': club['source_url'] + '/events/' + _slug(event.get('slug')),
        'publication_status': _public_text(event.get('status', 'unknown'), 'publication status'),
        'availability_state': _public_text(availability.get('state', 'unknown'), 'availability'),
        'requires_membership': membership,
    }


def _normalize_item(item):
    """Verify university, visibility and club identity before mapping one public event."""
    if not isinstance(item, dict):
        raise ValueError('A source event entry is not an object.')
    event, club = item.get('event'), item.get('club')
    availability = item.get('availability', {})
    if not all(isinstance(value, dict) for value in (event, club, availability)):
        raise ValueError('The event, club or availability object is missing.')
    if club.get('universitySlug') != config.UNICLUBS_UNIVERSITY:
        raise ValueError('The source contains data for another university.')
    if event.get('visibility') != 'public':
        raise ValueError('The source contains a nonpublic event.')
    if event.get('clubId') != club.get('id'):
        raise ValueError('The event and club identifiers do not match.')
    normalized_club = _club_record(club)
    return normalized_club, _event_record(event, normalized_club, availability)


def _clock(now):
    """Return an injected aware datetime or the current UTC time for the entire import."""
    if now is None:
        return datetime.now(timezone.utc)
    if not isinstance(now, datetime) or now.tzinfo is None or now.utcoffset() is None:
        raise ValueError('now must be a timezone-aware datetime.')
    return now.astimezone(timezone.utc)


def _select_future(source, detail_paths, now):
    """Validate the full source and select future starts, counting ongoing offers separately."""
    cutoff = now.isoformat(timespec='microseconds').replace('+00:00', 'Z')
    all_paths, seen_ids, clubs, future_clubs = set(), set(), {}, {}
    future, normalized, ongoing = [], [], 0
    for item in source:
        club, event = _normalize_item(item)
        identifier = event['external_id']
        if identifier in seen_ids:
            raise ValueError('The source repeats an event identifier.')
        seen_ids.add(identifier)
        club_id = club['external_id']
        if club_id in clubs and clubs[club_id] != club:
            raise ValueError('The source contains conflicting club information.')
        clubs[club_id] = club
        path = urlsplit(event['source_url']).path
        if path in all_paths:
            raise ValueError('Two source events share the same detail link.')
        all_paths.add(path)
        normalized.append(event)
        if event['start_utc'] >= cutoff:
            future.append(event)
            future_clubs[club_id] = club
        elif event['end_utc'] is not None and event['end_utc'] >= cutoff:
            ongoing += 1
    required = {urlsplit(event['source_url']).path for event in future}
    # Known past links may linger briefly while the response is being fetched.
    if not required <= detail_paths or not detail_paths <= all_paths:
        raise ValueError('The event data and visible public event links do not match.')
    return list(future_clubs.values()), future, ongoing, list(clubs.values()), normalized


def parse_events_page(html, now=None, allow_no_future=False):
    """Return validated future event/club records and source counts, without writing data.

    :param html: the public overview's complete HTML string
    :param now: optional aware clock; events starting at or after it are selected
    :param allow_no_future: allow a nonempty source with no future starts during synchronization
    :return: future clubs/events, full source_clubs/source_events, and source counts
    """
    now = _clock(now)
    if not isinstance(html, str) or len(html.encode('utf-8')) > config.UNICLUBS_MAX_HTML_BYTES:
        raise ValueError('The public event page is invalid or too large.')
    page = UniClubsPage()
    page.feed(html)
    page.close()
    if page.in_script:
        raise ValueError('The event page contains an incomplete script.')
    source = _extract_events(page)
    clubs, events, ongoing, source_clubs, source_events = _select_future(
        source, page.detail_paths, now)
    if not events and not allow_no_future:
        raise ValueError('No future public events were found; no catalog data was changed.')
    events.sort(key=lambda event: (event['start_utc'], event['external_id']))
    clubs.sort(key=lambda club: club['external_id'])
    return {'clubs': clubs, 'events': events, 'source_clubs': source_clubs,
            'source_events': source_events, 'source_event_count': len(source),
            'future_event_count': len(events), 'ongoing_event_count': ongoing,
            'rendered_event_count': len(page.detail_paths)}


def verify_sitemap(report, xml):
    """Require the public sitemap's HSG event links to match the entire parsed source.

    A concurrent website edit can also cause a mismatch; either case preserves the catalog.
    :param report: parsed overview report including source_events
    :param xml: complete public sitemap text
    :return: None; ValueError if this snapshot cannot be verified
    """
    if not isinstance(xml, str) or len(xml.encode('utf-8')) > config.UNICLUBS_MAX_SITEMAP_BYTES:
        raise ValueError('The public sitemap is invalid or too large.')
    if '<!DOCTYPE' in xml.upper():
        raise ValueError('The public sitemap contains an unexpected document declaration.')
    try:
        root = ElementTree.fromstring(xml)
    except ElementTree.ParseError as error:
        raise ValueError('The public sitemap could not be decoded.') from error
    if root.tag.rsplit('}', 1)[-1] != 'urlset':
        raise ValueError('A complete public sitemap URL list is required.')
    paths = set()
    for item in root.iter():
        if item.tag.rsplit('}', 1)[-1] == 'loc' and item.text:
            url = item.text.strip()
            if url.startswith(config.UNICLUBS_BASE_URL + '/'):
                path = _detail_path(url)
                if path:
                    paths.add(path)
    expected = {urlsplit(event['source_url']).path for event in report['source_events']}
    if not paths or paths != expected:
        raise ValueError('The event overview and public sitemap do not match; data unchanged.')


def run_import(connection, now=None):
    """Fetch and save the first catalog, logging failures without raw network details.

    :param connection: an initialized, idle catalog with no clubs or events
    :param now: optional aware clock shared by filtering and the stored observation times
    :return: the parsed report plus clubs_inserted and events_inserted
    """
    uniclubs_database.ensure_initial_import_allowed(connection)
    now = _clock(now)
    try:
        report = parse_events_page(importers.fetch_uniclubs_events_html(), now=now)
        counts = uniclubs_database.insert_initial_catalog(
            connection, report['clubs'], report['events'], now=now)
    except (ValueError, sqlite3.Error):
        uniclubs_database.record_import(
            connection, 'error', message='Initial public event import failed; data unchanged.',
            now=now)
        raise
    report.update(counts)
    return report


def run_sync(connection, now=None):
    """Fetch a verified snapshot and atomically add, update or flag missing catalog events.

    :param connection: initialized, idle UniClubs catalog connection, empty or populated
    :param now: optional aware clock shared by filtering and observation timestamps
    :return: parsed source report plus per-operation club and event counts
    """
    if connection.in_transaction:
        raise ValueError('Finish the current transaction before synchronizing events.')
    now = _clock(now)
    try:
        html, xml = importers.fetch_uniclubs_sync_documents()
        report = parse_events_page(html, now=now, allow_no_future=True)
        verify_sitemap(report, xml)
        counts = uniclubs_database.sync_catalog(
            connection, report['source_clubs'], report['source_events'], now=now)
    except (ValueError, sqlite3.Error):
        uniclubs_database.record_import(
            connection, 'error', message='Public event synchronization failed; data unchanged.',
            now=now)
        raise
    report.update(counts)
    return report


if __name__ == '__main__':
    connection = uniclubs_database.get_connection()
    try:
        uniclubs_database.init_db(connection)
        result = run_sync(connection)
        print(f'UniClubs events: {result["events_added"]} added, '
              f'{result["events_updated"]} updated, {result["events_unchanged"]} unchanged.')
        print(f'Missing from verified source: {result["events_missing"]}; '
              f'restored: {result["events_restored"]}. No events deleted.')
    except (ValueError, sqlite3.Error) as error:
        print(f'Import not completed: {error}')
        raise SystemExit(1)
    finally:
        connection.close()
